<template>
 <div class="virtual-editor">
  <div class="editor-toolbar"><el-button @click="cancel">返回</el-button><span class="text-12 secondary">组合规则保存后可供多张图表使用</span><span class="spacer"/><span v-if="dirty" class="text-12 muted">有未保存修改</span><el-button @click="exportDefinition">导出规则备份</el-button><el-button :loading="previewing" :disabled="loading||saving||cfg.sources.length<2" @click="preview">预览结果</el-button><el-button type="primary" :loading="saving" :disabled="loading||!name.trim()||!previewCurrent||saving" @click="save">保存虚拟表</el-button></div>
  <el-alert v-if="failure" :title="failure" type="error" :closable="false" show-icon/>
  <div v-if="loading" class="empty-hint">正在读取表格与组合规则…</div>
  <template v-else>
   <div class="virtual-setup" :inert="saving">
    <section class="source-panel"><h2>1 · 选择来源</h2><el-form label-position="top"><el-form-item label="虚拟表名称" for="virtual-name"><el-input id="virtual-name" v-model="name" maxlength="100" placeholder="例如：合并明细、计划实际对比" :disabled="saving"/></el-form-item><el-form-item label="来源原表（2–8 张）"><el-select :model-value="selectedIds" multiple filterable collapse-tags :max-collapse-tags="2" placeholder="选择要组合的原表" aria-label="来源原表" :disabled="saving||loadingSources" @change="changeSources"><el-option v-for="t in available" :key="t.id" :value="t.id" :label="t.name"/></el-select></el-form-item></el-form><div v-for="s in cfg.sources" :key="s.alias" class="source-card"><strong>{{ sourceName(s.alias) }}</strong><span class="text-12 muted">{{ info[s.table_id]?.fields?.length??'—' }} 列 · {{ info[s.table_id]?.record_count??'—' }} 行</span><router-link :to="`/data/${s.table_id}`">打开原表</router-link></div><p class="text-12 secondary">选择已有原表，虚拟表仅保存规则。原表更新后，下次读取或刷新会重新计算。</p><el-input v-model="note" type="textarea" :rows="3" maxlength="2000" placeholder="组合规则说明（可选）"/></section>
    <section class="rules-panel"><h2>2 · 组合与输出字段</h2><el-radio-group :model-value="cfg.mode" :disabled="saving" @change="changeMode"><el-radio-button value="union">上下追加</el-radio-button><el-radio-button value="join">按字段关联</el-radio-button><el-radio-button value="align">汇总后对齐</el-radio-button></el-radio-group><p class="text-13 secondary">{{ modeDescriptions[cfg.mode] }}</p>
     <template v-if="cfg.mode!=='union'">
      <div class="rule-section-head"><h3>匹配键</h3><el-button text :disabled="cfg.keys.length>=3||saving" @click="addKey">添加匹配键</el-button></div><div class="mapping-scroll"><table class="mapping-table key-mapping"><thead><tr><th>输出名称</th><th>类型</th><th v-for="s in cfg.sources" :key="s.alias">{{ sourceName(s.alias) }}</th><th/></tr></thead><tbody><tr v-for="(k,i) in cfg.keys" :key="k.key"><td><el-input v-model="k.name" maxlength="50" :aria-label="`匹配键${i+1}名称`"/></td><td><el-select v-model="k.type" :aria-label="`匹配键${i+1}类型`"><el-option v-for="t in virtualTypes.filter(t=>t.value!=='formula')" :key="t.value" :label="t.label" :value="t.value"/></el-select></td><td v-for="s in cfg.sources" :key="s.alias"><el-select v-model="k.fields[s.alias]" filterable placeholder="选择匹配字段" :aria-label="`${sourceName(s.alias)}匹配字段${i+1}`"><el-option v-for="f in sourceFields(s.alias).filter(f=>keyEligible(f.type))" :key="f.key" :label="f.name" :value="f.key"/></el-select></td><td><el-button text type="danger" :disabled="saving" @click="cfg.keys.splice(i,1)">移除</el-button></td></tr></tbody></table></div><p class="text-12 muted">按匹配键精确匹配，空键不互相匹配；数字按数值比较，单选按选项名称比较。</p>
      <div v-if="cfg.mode==='join'" class="join-options"><el-select v-model="cfg.join_type" aria-label="关联方式"><el-option label="保留首张表全部记录（左关联）" value="left"/><el-option label="只保留全部匹配的记录（内关联）" value="inner"/><el-option label="保留所有表的记录（全关联）" value="full"/></el-select><el-checkbox v-model="cfg.allow_many">允许重复键匹配，已了解可能重复累计</el-checkbox></div>
     </template>
     <div class="rule-section-head"><h3>输出字段</h3><div class="toolbar-actions"><el-button text :disabled="cfg.sources.length<2||saving" @click="rebuild">自动配置字段</el-button><el-button :disabled="outputFields.length>=50||saving" @click="addColumn(false)">添加输出列</el-button><el-button :disabled="outputFields.length>=50||saving" @click="addColumn(true)">添加计算列</el-button></div></div>
     <div class="mapping-scroll"><table class="mapping-table"><thead><tr><th>输出名称</th><th>类型</th><template v-if="cfg.mode==='union'"><th v-for="s in cfg.sources" :key="s.alias">{{ sourceName(s.alias) }}</th></template><template v-else><th>来源表</th><th>来源字段</th><th v-if="cfg.mode==='align'">汇总方式</th></template><th>公式 / 操作</th></tr></thead><tbody><tr v-for="(c,i) in cfg.columns" :key="c.key"><td><el-input v-model="c.name" maxlength="50" :aria-label="`输出列${i+1}名称`" placeholder="字段名称"/></td><td><el-select v-model="c.type" :aria-label="`输出列${i+1}类型`"><el-option v-for="t in virtualTypes.filter(t=>cfg.mode!=='align'||['number','formula'].includes(t.value))" :key="t.value" :label="t.label" :value="t.value"/></el-select></td><template v-if="cfg.mode==='union'"><td v-for="s in cfg.sources" :key="s.alias"><el-select v-if="c.type!=='formula'" v-model="c.mapping[s.alias]" clearable filterable placeholder="留空补空值" :aria-label="`${sourceName(s.alias)}输出字段${i+1}`"><el-option v-for="f in sourceFields(s.alias)" :key="f.key" :label="f.name" :value="f.key"/></el-select><span v-else class="text-12 muted">结果计算</span></td></template><template v-else><td><el-select v-if="c.type!=='formula'" v-model="c.source" :aria-label="`输出列${i+1}来源表`" @change="c.field=null"><el-option v-for="s in cfg.sources" :key="s.alias" :label="sourceName(s.alias)" :value="s.alias"/></el-select></td><td><el-select v-if="c.type!=='formula'&&!(cfg.mode==='align'&&c.aggregation==='count')" v-model="c.field" filterable placeholder="选择字段" :aria-label="`输出列${i+1}来源字段`"><el-option v-for="f in sourceFields(c.source||'').filter(f=>cfg.mode!=='align'||['number','formula','rollup'].includes(f.type))" :key="f.key" :label="f.name" :value="f.key"/></el-select><span v-else-if="c.aggregation==='count'" class="text-12 muted">统计来源行数</span></td><td v-if="cfg.mode==='align'"><el-select v-if="c.type!=='formula'" v-model="c.aggregation" :aria-label="`输出列${i+1}汇总方式`"><el-option v-for="(label,key) in aggregations" :key="key" :label="label" :value="key"/></el-select></td></template><td class="formula-action"><el-input v-if="c.type==='formula'" v-model="c.expression" :aria-label="`输出列${i+1}公式`" placeholder="例如：{计划}-{实际}" @input="c.bindings={}"/><el-button text type="danger" :disabled="saving" @click="cfg.columns.splice(i,1)">移除</el-button></td></tr></tbody></table></div>
     <div class="rule-section-head"><h3>结果筛选与排序</h3><div class="toolbar-actions"><el-button text :disabled="cfg.filters.length>=10||!outputFields.length" @click="cfg.filters.push({field:outputFields[0].key,op:'eq',value:''})">添加筛选</el-button><el-button text :disabled="cfg.sorts.length>=3||!outputFields.length" @click="cfg.sorts.push({field:outputFields[0].key,order:'asc'})">添加排序</el-button></div></div>
     <div v-for="(f,i) in cfg.filters" :key="'filter'+i" class="query-line"><el-select v-model="f.field" aria-label="结果筛选字段"><el-option v-for="o in outputFields" :key="o.key" :label="o.name||'未命名列'" :value="o.key"/></el-select><el-select v-model="f.op" aria-label="结果筛选方式"><el-option v-for="(label,key) in filterOps" :key="key" :label="label" :value="key"/></el-select><el-input v-if="!['empty','not_empty'].includes(f.op)" v-model="f.value" placeholder="筛选值"/><el-button text @click="cfg.filters.splice(i,1)">移除</el-button></div>
     <div v-for="(s,i) in cfg.sorts" :key="'sort'+i" class="query-line"><el-select v-model="s.field" aria-label="结果排序字段"><el-option v-for="o in outputFields" :key="o.key" :label="o.name||'未命名列'" :value="o.key"/></el-select><el-select v-model="s.order" aria-label="结果排序方向"><el-option label="升序" value="asc"/><el-option label="降序" value="desc"/></el-select><el-button text @click="cfg.sorts.splice(i,1)">移除</el-button></div>
    </section>
   </div>
   <section class="preview-panel" :inert="saving"><div class="rule-section-head"><h2>3 · 结果预览</h2><el-button :loading="previewing" :disabled="cfg.sources.length<2||saving" @click="preview">重新预览</el-button></div><el-alert v-if="previewResult&&!previewCurrent" title="组合规则已变化，请重新预览后保存。" type="warning" :closable="false"/>
    <template v-if="previewResult"><div class="preview-summary"><el-tag>{{ previewResult.total }} 行结果</el-tag><span v-for="s in previewResult.sources" :key="s.alias" class="text-12 secondary">{{ s.name }}：{{ s.rows }} 行<template v-if="s.unmatched_rows"> · {{ s.unmatched_rows }} 行未进入结果</template></span><span class="text-12 muted">预览前 100 行，统计基于全部结果</span></div><el-alert v-for="w in previewResult.warnings" :key="w" :title="w" type="warning" :closable="false"/><el-table class="virtual-result-preview" :data="previewResult.records" max-height="380" border><el-table-column v-for="f in previewResult.fields" :key="f.key" :label="f.name" min-width="150"><template #default="{row}"><span v-if="row.computed_errors?.[f.key]" class="error-text">#ERROR · {{ row.computed_errors[f.key] }}</span><span v-else>{{ display(f,row.data[f.key]) }}</span></template></el-table-column><el-table-column label="来源条数" width="100"><template #default="{row}">{{ row.origin_count }}</template></el-table-column></el-table></template><div v-else class="empty-hint">选择来源和组合规则后，点击“预览结果”检查数据。</div>
   </section>
  </template>
 </div>
</template>
<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref} from 'vue'
import {onBeforeRouteLeave,useRoute,useRouter} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {http,apiError} from '@/api/client'
import {display} from '@/table-core'
import {emptyDefinition,newVirtualColumn,outputType,virtualKey,virtualTypes,type VirtualDefinition,type VirtualSource,type VirtualColumn} from '@/virtual-table'
const route=useRoute(),router=useRouter(),id=Number(route.params.tableId)||null,name=ref(''),note=ref(''),version=ref(1),cfg=reactive<VirtualDefinition>(emptyDefinition()),available=ref<any[]>([]),info=reactive<Record<number,any>>({}),loading=ref(true),loadingSources=ref(false),saving=ref(false),previewing=ref(false),failure=ref(''),previewResult=ref<any>(),previewHash=ref(''),baseline=ref('')
let sourceRequest=0,active=true
const modeDescriptions={union:'把多张表的行上下追加。按字段映射对齐列，未映射的来源列补空值。',join:'按共同字段匹配记录，再把各表字段并列展示。首张表是左关联的主表。',align:'每张表先按匹配键分组汇总，再对齐各表指标，避免明细直接关联造成重复累计。'}
const aggregations={sum:'求和',avg:'平均',min:'最小',max:'最大',count:'记录数'},filterOps={eq:'等于',ne:'不等于',contains:'包含',gt:'大于',gte:'大于等于',lt:'小于',lte:'小于等于',empty:'为空',not_empty:'不为空'}
const selectedIds=computed(()=>cfg.sources.map(s=>s.table_id)),outputFields=computed(()=>[...(cfg.mode==='union'?[]:cfg.keys),...cfg.columns]),signature=()=>JSON.stringify({name:name.value,note:note.value,definition:cfg}),dirty=computed(()=>!loading.value&&signature()!==baseline.value),previewCurrent=computed(()=>!!previewResult.value&&JSON.stringify(cfg)===previewHash.value)
function sourceName(alias:string){const s=cfg.sources.find(s=>s.alias===alias);return s?info[s.table_id]?.name||available.value.find(t=>t.id===s.table_id)?.name||`原表 #${s.table_id}`:'选择来源'}
function sourceFields(alias:string):any[]{const s=cfg.sources.find(s=>s.alias===alias);return s?info[s.table_id]?.fields||[]:[]}
const keyEligible=(type:string)=>['short_text','long_text','select','url','date','number','formula','rollup','checkbox'].includes(type)
async function fetchSources(){const ticket=++sourceRequest;loadingSources.value=true;try{const results=await Promise.allSettled(cfg.sources.map(s=>http.get(`/tables/${s.table_id}`)));if(!active||ticket!==sourceRequest)return;let message='';results.forEach((r,i)=>{if(r.status==='fulfilled')info[cfg.sources[i].table_id]=r.value.data;else message=apiError(r.reason).message});if(message)failure.value='来源读取失败：'+message}finally{if(ticket===sourceRequest)loadingSources.value=false}}
async function changeSources(ids:number[]){if(ids.length>8){failure.value='一次最多选择 8 张原表';return}cfg.sources=ids.map(table_id=>cfg.sources.find(s=>s.table_id===table_id)||{alias:'s_'+crypto.randomUUID().slice(0,8),table_id});const aliases=new Set(cfg.sources.map(s=>s.alias));for(const c of cfg.columns){for(const a of Object.keys(c.mapping))if(!aliases.has(a))delete c.mapping[a];if(c.source&&!aliases.has(c.source)){c.source=null;c.field=null}}for(const k of cfg.keys)for(const a of Object.keys(k.fields))if(!aliases.has(a))delete k.fields[a];failure.value='';await fetchSources();if(!cfg.columns.length&&cfg.sources.length>=2)autoFields()}
function addKey(){cfg.keys.push({key:virtualKey(),name:cfg.keys.length?'匹配键'+(cfg.keys.length+1):'匹配键',type:'short_text',fields:{}})}
function guessKey(){const first=cfg.sources[0];if(!first)return;const common=sourceFields(first.alias).find(f=>keyEligible(f.type)&&cfg.sources.every(s=>sourceFields(s.alias).some(x=>x.name===f.name&&outputType(x.type)===outputType(f.type))));if(common)cfg.keys=[{key:virtualKey(),name:common.name,type:outputType(common.type),fields:Object.fromEntries(cfg.sources.map(s=>[s.alias,sourceFields(s.alias).find(f=>f.name===common.name&&outputType(f.type)===outputType(common.type)).key]))}];else addKey()}
function autoFields(){const old=new Map(cfg.columns.map(c=>[c.name,c]));if(cfg.mode!=='union'&&!cfg.keys.length)guessKey();const result:VirtualColumn[]=[],names=new Set(cfg.mode==='union'?[]:cfg.keys.map(k=>k.name));function unique(raw:string){let n=raw.slice(0,50),i=2;while(names.has(n))n=raw.slice(0,45)+' '+i++;names.add(n);return n}
 if(cfg.mode==='union'){const seen=new Set<string>();for(const s of cfg.sources)for(const f of sourceFields(s.alias)){if(seen.has(f.name)||result.length>=50)continue;seen.add(f.name);const type=outputType(f.type),c=newVirtualColumn(unique(f.name),type);c.key=old.get(c.name)?.key||c.key;for(const other of cfg.sources){const match=sourceFields(other.alias).find(x=>x.name===f.name&&outputType(x.type)===type);if(match)c.mapping[other.alias]=match.key}result.push(c)}}
 else for(const s of cfg.sources){if(result.length+cfg.keys.length>=50)break;let fields=sourceFields(s.alias).filter(f=>cfg.mode==='align'?['number','formula','rollup'].includes(f.type):!cfg.keys.some(k=>k.fields[s.alias]===f.key));if(cfg.mode==='align'&&!fields.length){const c=newVirtualColumn(unique(sourceName(s.alias)+' · 记录数'),'number');c.source=s.alias;c.aggregation='count';result.push(c)}else for(const f of fields){if(result.length+cfg.keys.length>=50)break;const c=newVirtualColumn(unique(sourceName(s.alias)+' · '+f.name),cfg.mode==='align'?'number':outputType(f.type));c.key=old.get(c.name)?.key||c.key;c.source=s.alias;c.field=f.key;result.push(c)}}
 cfg.columns=result;cfg.filters=[];cfg.sorts=[]
}
async function rebuild(){try{if(cfg.columns.length)await ElMessageBox.confirm('根据当前来源重新配置输出字段，已有自定义字段、筛选和排序将被替换，引用已移除字段的图表需要重新配置。','重新配置字段',{confirmButtonText:'重新配置',cancelButtonText:'取消'});autoFields()}catch{}}
async function changeMode(value:any){if(value===cfg.mode)return;try{if(cfg.columns.length)await ElMessageBox.confirm('切换组合方式会重建匹配键、输出字段、筛选和排序，引用已移除字段的图表需要重新配置。','切换组合方式',{confirmButtonText:'切换并重建',cancelButtonText:'取消'});cfg.mode=value;cfg.keys=[];autoFields()}catch{}}
function addColumn(formula:boolean){const c=newVirtualColumn(formula?'计算列'+(cfg.columns.filter(c=>c.type==='formula').length+1):'',formula?'formula':cfg.mode==='align'?'number':'short_text');if(!formula&&cfg.mode!=='union')c.source=cfg.sources[0]?.alias||null;cfg.columns.push(c)}
function payloadDefinition(){const d=JSON.parse(JSON.stringify(cfg));for(const c of d.columns){c.mapping=Object.fromEntries(Object.entries(c.mapping||{}).filter(([,v])=>v));if(c.type==='formula'){c.mapping={};c.source=null;c.field=null}}return d}
async function preview(){if(previewing.value||saving.value)return;previewing.value=true;failure.value='';const at=JSON.stringify(cfg);try{const {data}=await http.post('/virtual-tables/preview',{definition:payloadDefinition()});if(!active)return;previewResult.value=data;previewHash.value=at}catch(e){failure.value=apiError(e).message;previewResult.value=null;previewHash.value=''}finally{previewing.value=false}}
async function save(){if(!previewCurrent.value||saving.value)return;saving.value=true;failure.value='';try{const payload={name:name.value.trim(),note:note.value,definition:payloadDefinition(),version:id?version.value:undefined};const {data}=id?await http.put(`/virtual-tables/${id}`,payload):await http.post('/virtual-tables',payload);baseline.value=signature();window.dispatchEvent(new Event('wb:tables-changed'));await router.replace(`/data/${data.id}`)}catch(e){failure.value=apiError(e).message}finally{saving.value=false}}
function exportDefinition(){const url=URL.createObjectURL(new Blob([JSON.stringify({name:name.value,note:note.value,definition:payloadDefinition()},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=(name.value||'虚拟表')+'.virtual.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function cancel(){router.push(id?`/data/${id}`:'/data')}
onBeforeRouteLeave(async()=>{if(saving.value&&signature()!==baseline.value)return false;if(!dirty.value)return true;try{await ElMessageBox.confirm('尚未保存的虚拟表规则将被放弃，可先导出规则备份。','离开虚拟表编辑',{confirmButtonText:'放弃并离开',cancelButtonText:'继续编辑'});return true}catch{return false}})
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);try{available.value=(await http.get('/tables')).data.filter((t:any)=>t.kind!=='virtual');if(id){const t=(await http.get(`/tables/${id}`)).data;if(t.kind!=='virtual')throw new Error('此表不是虚拟表');name.value=t.name;note.value=t.note||'';version.value=t.schema_version;Object.assign(cfg,t.virtual_config);await fetchSources()}else if(route.query.source){const tid=Number(route.query.source);if(available.value.some(t=>t.id===tid)){cfg.sources=[{alias:'s_'+crypto.randomUUID().slice(0,8),table_id:tid}];await fetchSources()}}baseline.value=signature()}catch(e:any){failure.value=e.response?apiError(e).message:e.message}finally{loading.value=false}})
onUnmounted(()=>{active=false;sourceRequest++;window.removeEventListener('beforeunload',beforeUnload)})
</script>
